    binding,
    report: {
      calibration,
      runs: Array.from({ length: 10 }, () => ({
        stats: worstNumeric({ frame: { p50: 1, p95: 1, p99: 1, max: 1, count: 30000 } }),
        memory: { wheelMeshes: 280, chassisMeshes: 70, worlds: 1 },
      })),
    },
    lifetime: { causes, journal },
    state: 'INCOMPLETE',
  };
