    await mkdir(join(archive, 'source'), { recursive: true });
    await mkdir(join(archive, 'build'), { recursive: true });
    await mkdir(join(archive, 'native'), { recursive: true });
    await mkdir(capture);
    const source = Buffer.from('old-source'),
      artifact = Buffer.from('old-artifact'),
      native = Buffer.from('old-native'),
      hardware = Buffer.from('{"purpose":"TEST_ONLY"}');
    const sourceHash = createHash('sha256').update('helper.mjs').update(source).digest('hex');
    const artifacts = [{ path: 'index.js', bytes: artifact.length, sha256: hash(artifact) }],
      artifactHash = hash(JSON.stringify(artifacts));
    const binding = {
      captureId,
      protocol: PROTOCOL,
      archive: archiveName,
      sourceHash,
      artifactHash,
      inputs: ['helper.mjs'],
      native: { bytes: native.length, sha256: hash(native) },
      hardware: { bytes: hardware.length, sha256: hash(hardware) },
